CREATE TABLE IF NOT EXISTS alerts (
	id SERIAL NOT NULL, 
	alert_id VARCHAR(24) NOT NULL, 
	alert_type VARCHAR(40) NOT NULL, 
	classification VARCHAR(40), 
	status VARCHAR(40), 
	routing_status VARCHAR(50), 
	dedupe_key VARCHAR(160), 
	region_id VARCHAR(120), 
	region_name VARCHAR(200), 
	state VARCHAR(80), 
	district_id VARCHAR(60), 
	land_use VARCHAR(40), 
	probability FLOAT, 
	p_lower FLOAT, 
	p_upper FLOAT, 
	risk_category VARCHAR(12), 
	issue_date DATE, 
	generated_at TIMESTAMP WITHOUT TIME ZONE, 
	last_evaluated TIMESTAMP WITHOUT TIME ZONE, 
	priority INTEGER, 
	payload JSON, 
	supersedes VARCHAR(24), 
	PRIMARY KEY (id), 
	UNIQUE (alert_id)
);
CREATE INDEX IF NOT EXISTS ix_alert_generated ON alerts (generated_at);
CREATE INDEX IF NOT EXISTS ix_alert_key_status ON alerts (dedupe_key, status);
